package com.clas.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.clas.entity.*; import com.clas.mapper.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.List;
@Service public class RiderOverdueService { private final OrdersMapper orders; private final DeliveryExceptionMapper exceptions; private final RiderSettlementMapper settlements;
 public RiderOverdueService(OrdersMapper orders,DeliveryExceptionMapper exceptions,RiderSettlementMapper settlements){this.orders=orders;this.exceptions=exceptions;this.settlements=settlements;}
 @Scheduled(fixedDelayString="${app.rider-overdue.scan-delay-ms:60000}") @Transactional public void scan(){List<Orders> late=orders.selectList(new LambdaQueryWrapper<Orders>().in(Orders::getDeliveryStatus,"ASSIGNED_WAITING_MEAL","DELIVERING","DELIVERED").lt(Orders::getPromiseEndAt,LocalDateTime.now()).isNotNull(Orders::getRiderId));late.forEach(this::recordOnce);}
 void recordOnce(Orders o){if(exceptions.selectCount(new LambdaQueryWrapper<DeliveryException>().eq(DeliveryException::getOrderId,o.getId()).eq(DeliveryException::getExceptionType,"OVERDUE"))>0)return;int deduction=Math.round((o.getRiderCommission()==null?0:o.getRiderCommission())*.2f);DeliveryException e=new DeliveryException();e.setOrderId(o.getId());e.setRiderId(o.getRiderId());e.setExceptionType("OVERDUE");e.setStatus("OPEN");e.setScoreDeduction(5);e.setCommissionDeduction(deduction);e.setDetail("超过原承诺送达时间");e.setCreatedAt(LocalDateTime.now());exceptions.insert(e);if(deduction>0){RiderSettlement s=new RiderSettlement();s.setRiderId(o.getRiderId());s.setOrderId(o.getId());s.setSourceType("OVERDUE_DEDUCTION");s.setSourceId(String.valueOf(o.getId()));s.setSettlementType("DEDUCTION");s.setAmount(-deduction);s.setBalanceType("PENDING");s.setCreatedAt(LocalDateTime.now());settlements.insert(s);}}
}
